import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

__device__ __forceinline__ float4 sigmoid4(float4 v) {
    v.x = 1.0f / (1.0f + __expf(-v.x));
    v.y = 1.0f / (1.0f + __expf(-v.y));
    v.z = 1.0f / (1.0f + __expf(-v.z));
    v.w = 1.0f / (1.0f + __expf(-v.w));
    return v;
}
__global__ void __launch_bounds__(256) sigmoid_kernel_vec4(const float4* __restrict__ in,
                                    float4* __restrict__ out,
                                    long n4) {
    long idx = (long)blockIdx.x * blockDim.x + threadIdx.x;
    long stride = (long)gridDim.x * blockDim.x;
    long i = idx;
    for (; i + 3 * stride < n4; i += 4 * stride) {
        float4 v0 = __ldcs(&in[i]);
        float4 v1 = __ldcs(&in[i + stride]);
        float4 v2 = __ldcs(&in[i + 2 * stride]);
        float4 v3 = __ldcs(&in[i + 3 * stride]);
        v0 = sigmoid4(v0);
        v1 = sigmoid4(v1);
        v2 = sigmoid4(v2);
        v3 = sigmoid4(v3);
        __stcs(&out[i], v0);
        __stcs(&out[i + stride], v1);
        __stcs(&out[i + 2 * stride], v2);
        __stcs(&out[i + 3 * stride], v3);
    }
    for (; i < n4; i += stride) {
        __stcs(&out[i], sigmoid4(__ldcs(&in[i])));
    }
}

__global__ void sigmoid_kernel_tail(const float* __restrict__ in,
                                    float* __restrict__ out,
                                    long start, long n) {
    long idx = start + (long)blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        float v = __ldcs(&in[idx]);
        __stcs(&out[idx], 1.0f / (1.0f + __expf(-v)));
    }
}

torch::Tensor sigmoid_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    auto x_contig = x.contiguous();
    auto out = torch::empty_like(x_contig);

    long n = x_contig.numel();
    if (n == 0) return out;

    const float* in_ptr = x_contig.data_ptr<float>();
    float* out_ptr = out.data_ptr<float>();

    long n4 = n / 4;
    long rem_start = n4 * 4;

    if (n4 > 0) {
        int threads = 256;
        long want_blocks = (n4 + (long)threads - 1) / (long)threads;
        int sms = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
        int blocks_per_sm = 0;
        cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks_per_sm, sigmoid_kernel_vec4, threads, 0);
        if (blocks_per_sm < 1) blocks_per_sm = 1;
        long full_wave_blocks = (long)sms * blocks_per_sm;
        long max_blocks = full_wave_blocks * 4;
        int blocks = (int)std::min(want_blocks, max_blocks);
        sigmoid_kernel_vec4<<<blocks, threads>>>(
            reinterpret_cast<const float4*>(in_ptr),
            reinterpret_cast<float4*>(out_ptr),
            n4);
    }

    if (rem_start < n) {
        int threads = 256;
        int blocks = (int)((n - rem_start + threads - 1) / threads);
        sigmoid_kernel_tail<<<blocks, threads>>>(in_ptr, out_ptr, rem_start, n);
    }

    return out;
}
"""

cpp_src = "torch::Tensor sigmoid_forward(torch::Tensor x);"

sigmoid_mod = load_inline(
    name="sigmoid_cuda_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["sigmoid_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Sigmoid activation using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return sigmoid_mod.sigmoid_forward(x)

